// cw-multitest — evals/fixtures/lending_drain_test.rs (written here, NOT executed — see step 0.5 discipline)
use cosmwasm_std::{Uint128, coins};
use cw_multi_test::{App, ContractWrapper, Executor};

#[test]
fn test_withdraw_without_deposit_corrupts_accounting() {
    let mut app = App::default();
    let code = ContractWrapper::new(execute, instantiate, query);
    let code_id = app.store_code(Box::new(code));
    let contract_addr = app.instantiate_contract(
        code_id, Addr::unchecked("admin"), &InstantiateMsg {}, &[], "lending", None,
    ).unwrap();

    // Honest depositor deposits 1000 uzig.
    app.execute_contract(
        Addr::unchecked("honest_depositor"), contract_addr.clone(),
        &ExecuteMsg::Deposit {}, &coins(1000, "uzig"),
    ).unwrap();

    let total_before: Config = app.wrap().query_wasm_smart(&contract_addr, &()).unwrap();
    assert_eq!(total_before.total_deposits, Uint128::new(1000));

    // Attacker who deposited nothing calls Withdraw for 1000 uzig -- their own deposit
    // record (which doesn't exist) is never consulted.
    let result = app.execute_contract(
        Addr::unchecked("attacker"), contract_addr.clone(),
        &ExecuteMsg::Withdraw { amount: Uint128::new(1000) }, &[],
    );

    // THE REAL INVARIANT: total_deposits accounting must not be reduced by a caller who
    // never contributed to it -- checking result.is_err() alone is insufficient, since
    // the exploit's whole point is that the call currently SUCCEEDS and silently corrupts
    // the accounting (whether or not real bank funds also move is a separate question --
    // see the fixture's own 'not_a_vulnerability_but_might_be_flagged' note).
    let total_after: Config = app.wrap().query_wasm_smart(&contract_addr, &()).unwrap();
    assert!(
        result.is_err() || total_after.total_deposits == total_before.total_deposits,
        "attacker with zero deposits reduced total_deposits from {} to {}",
        total_before.total_deposits, total_after.total_deposits
    );
}
